SELECT 'TSIBAI_TOTAL' OBJETO, COUNT(*) QTD FROM SANKHYA.TSIBAI
UNION ALL SELECT 'TSIEND_TOTAL', COUNT(*) FROM SANKHYA.TSIEND
UNION ALL SELECT 'R03_MAP_BAI', COUNT(*) FROM SANKHYA.RMD_CASA_2930_R03_MAP WHERE ID_EXECUCAO='RMD_CASA_2930_MRG_20260923_R03' AND TIPO='BAI'
UNION ALL SELECT 'R03_MAP_END', COUNT(*) FROM SANKHYA.RMD_CASA_2930_R03_MAP WHERE ID_EXECUCAO='RMD_CASA_2930_MRG_20260923_R03' AND TIPO='END'
UNION ALL SELECT 'R03_DEP', COUNT(*) FROM SANKHYA.RMD_CASA_2930_R03_DEP WHERE ID_EXECUCAO='RMD_CASA_2930_MRG_20260923_R03'
UNION ALL SELECT 'R03_EXC', COUNT(*) FROM SANKHYA.RMD_CASA_2930_R03_EXC WHERE ID_EXECUCAO='RMD_CASA_2930_MRG_20260923_R03'
UNION ALL SELECT 'R03_DEL_AUD', COUNT(*) FROM SANKHYA.RMD_CASA_2930_R03_DEL WHERE ID_EXECUCAO='RMD_CASA_2930_MRG_20260923_R03'
UNION ALL SELECT 'TGFPAR_REF_OBS', COUNT(*) FROM SANKHYA.TGFPAR t WHERE EXISTS (SELECT 1 FROM SANKHYA.RMD_CASA_2930_R03_MAP m WHERE m.ID_EXECUCAO='RMD_CASA_2930_MRG_20260923_R03' AND m.TIPO='BAI' AND m.COD_OBSOLETO=t.CODBAI) OR EXISTS (SELECT 1 FROM SANKHYA.RMD_CASA_2930_R03_MAP m WHERE m.ID_EXECUCAO='RMD_CASA_2930_MRG_20260923_R03' AND m.TIPO='END' AND m.COD_OBSOLETO=t.CODEND)
UNION ALL SELECT 'TSICEP_REF_OBS', COUNT(*) FROM SANKHYA.TSICEP t WHERE EXISTS (SELECT 1 FROM SANKHYA.RMD_CASA_2930_R03_MAP m WHERE m.ID_EXECUCAO='RMD_CASA_2930_MRG_20260923_R03' AND m.TIPO='BAI' AND m.COD_OBSOLETO=t.CODBAI) OR EXISTS (SELECT 1 FROM SANKHYA.RMD_CASA_2930_R03_MAP m WHERE m.ID_EXECUCAO='RMD_CASA_2930_MRG_20260923_R03' AND m.TIPO='END' AND m.COD_OBSOLETO=t.CODEND)
UNION ALL SELECT 'TGFCPL_REF_OBS', COUNT(*) FROM SANKHYA.TGFCPL t WHERE EXISTS (SELECT 1 FROM SANKHYA.RMD_CASA_2930_R03_MAP m WHERE m.ID_EXECUCAO='RMD_CASA_2930_MRG_20260923_R03' AND m.TIPO='BAI' AND m.COD_OBSOLETO IN (t.CODBAIENTREGA,t.CODBAIRECEB,t.CODBAITRAB)) OR EXISTS (SELECT 1 FROM SANKHYA.RMD_CASA_2930_R03_MAP m WHERE m.ID_EXECUCAO='RMD_CASA_2930_MRG_20260923_R03' AND m.TIPO='END' AND m.COD_OBSOLETO IN (t.CODENDENTREGA,t.CODENDRECEB,t.CODENDTRAB))
UNION ALL SELECT 'BKP_TGFPAR_NOVO_REF_OBS', COUNT(*) FROM SANKHYA.BKP_TGFPAR_NOVO t WHERE EXISTS (SELECT 1 FROM SANKHYA.RMD_CASA_2930_R03_MAP m WHERE m.ID_EXECUCAO='RMD_CASA_2930_MRG_20260923_R03' AND m.TIPO='BAI' AND m.COD_OBSOLETO=t.CODBAI) OR EXISTS (SELECT 1 FROM SANKHYA.RMD_CASA_2930_R03_MAP m WHERE m.ID_EXECUCAO='RMD_CASA_2930_MRG_20260923_R03' AND m.TIPO='END' AND m.COD_OBSOLETO=t.CODEND)
